/*
===============================================================================
DEFINICIÓN CANÓNICA VERSIONADA
Procedimiento: integracion_datos_analitica.usp_cargar_asesor_diario_claro

Corrección de calidad de identidad:
- una fila fuente sin nombre no debe borrar un nombre válido ya materializado;
- para la identidad descriptiva se prioriza la observación no nula más reciente;
- si el reporte no aporta nombre, se usa el maestro dbo.av_Usuario por el mismo
  id de usuario como fallback determinístico;
- si ninguna fuente aporta nombre, se conserva NULL en inserts y el valor
  existente en updates; no se inventa un nombre.

Preparado a partir de la definición de producción observada el 18/09/2026.
===============================================================================
*/

/* =====================================================================     1. ADVISOR CORREGIDO     ===================================================================== */    CREATE OR ALTER PROCEDURE [integracion_datos_analitica].[usp_cargar_asesor_diario_claro]     @id_cliente_crm       INT,     @fecha_corte            DATETIME2(3) = NULL,     @anio_campana       SMALLINT = NULL,     @mes_campana      TINYINT = NULL,     @nombre_cliente_origen  VARCHAR(150) = 'CLARO CORPORATIVO',     @codigo_unidad_negocio VARCHAR(20) = 'ADMINISTRATIVO' AS BEGIN     SET NOCOUNT ON;     SET XACT_ABORT ON;      SET @fecha_corte = ISNULL(@fecha_corte, SYSDATETIME());     SET @anio_campana = ISNULL(@anio_campana, YEAR(@fecha_corte));     SET @mes_campana = ISNULL(@mes_campana, MONTH(@fecha_corte));      IF @id_cliente_crm IS NULL OR @id_cliente_crm <= 0         THROW 51800, '@id_cliente_crm es obligatorio.', 1;      IF @mes_campana NOT BETWEEN 1 AND 12         THROW 51801, '@mes_campana debe estar entre 1 y 12.', 1;      SET @codigo_unidad_negocio =         UPPER(LTRIM(RTRIM(ISNULL(@codigo_unidad_negocio, ''))));      IF @codigo_unidad_negocio NOT IN ('ADMINISTRATIVO', 'GOBIERNO')         THROW 51820, '@codigo_unidad_negocio debe ser ADMINISTRATIVO o GOBIERNO.', 1;      DECLARE @business_unit_name VARCHAR(150) =         CASE @codigo_unidad_negocio             WHEN 'ADMINISTRATIVO' THEN 'CLARO ADMINISTRATIVO'             WHEN 'GOBIERNO' THEN 'CLARO GOBIERNO'         END;      DECLARE @resolved_source_client_name VARCHAR(150) =         CASE @codigo_unidad_negocio             WHEN 'ADMINISTRATIVO' THEN 'CLARO CORPORATIVO'             WHEN 'GOBIERNO' THEN 'CLARO GOBIERNO'         END;      DECLARE @watermark_source_code VARCHAR(100) =         CASE @codigo_unidad_negocio             WHEN 'ADMINISTRATIVO' THEN 'CLARO_ADVISOR_DAILY'             WHEN 'GOBIERNO' THEN 'CLARO_GOB_ADVISOR_DAILY'         END;      /* Parametro legacy conservado para compatibilidad; la BU manda. */     SET @nombre_cliente_origen = @resolved_source_client_name;      DECLARE @client_key INT;     DECLARE @campaign_key INT;      DECLARE @codigo_campana VARCHAR(20) =         CONCAT(             @anio_campana,             '-',             RIGHT(CONCAT('0', @mes_campana), 2)         );      DECLARE @campaign_start DATE =         DATEFROMPARTS(@anio_campana, @mes_campana, 1);      DECLARE @as_of_date DATE =         CONVERT(DATE, @fecha_corte);      DECLARE @end_exclusive DATETIME2(3) =         DATEADD(DAY, 1, CONVERT(DATETIME2(3), @as_of_date));      SELECT @client_key = clave_cliente     FROM analitica.dim_cliente     WHERE id_cliente_crm = @id_cliente_crm       AND es_activo = 1;      IF @client_key IS NULL         THROW 51802, 'Cliente no encontrado en analitica.dim_cliente.', 1;      SELECT @campaign_key = clave_campana     FROM analitica.dim_campana     WHERE clave_cliente = @client_key       AND codigo_campana = @codigo_campana;      IF @campaign_key IS NULL         THROW 51803, 'Campaña no encontrada en analitica.dim_campana.', 1;       /* ============================================================        1. Gestión real del mes         Excluye las filas sintéticas de pago.        ============================================================ */      IF OBJECT_ID('tempdb..#Source') IS NOT NULL         DROP TABLE #Source;      SELECT         p.clave_cartera,         t.nId_Cartera,         CONVERT(INT, t.nId_Usuario) AS id_asesor_origen,         CONVERT(INT, t.nId_UsuOpe) AS source_operator_id,         NULLIF(LTRIM(RTRIM(t.nombre_asesor)), '') AS nombre_asesor,         NULLIF(LTRIM(RTRIM(t.cNombre_Cargo)), '') AS nombre_rol,          CONVERT(BIGINT, t.nId_PersDeudor) AS id_deudor_origen,         CONVERT(BIGINT, t.nId_DocxCobrarOpe) AS id_operacion_origen,          CONVERT(DATETIME2(3), t.dDocCobOpe_FecIni) AS fecha_hora_gestion,         CONVERT(DATE, t.dDocCobOpe_FecIni) AS management_date,         CONVERT(             INT,             CONVERT(                 CHAR(8),                 CONVERT(DATE, t.dDocCobOpe_FecIni),                 112             )         ) AS clave_fecha,          UPPER(LTRIM(RTRIM(ISNULL(t.indicador_equiv, ''))))             AS contact_code,          CONVERT(BIT, ISNULL(t.marca_promesa_valida, 0))             AS is_valid_promise_source,          NULLIF(LTRIM(RTRIM(t.estado_pdp)), '')             AS estado_origen,          CONVERT(DECIMAL(19,4), ISNULL(t.montoPromesa, 0))             AS monto_promesa,          CONVERT(DECIMAL(19,4), ISNULL(t.total_pagado, 0))             AS monto_pagado,          CONVERT(DATETIME2(3), t.fecha_proceso)             AS fecha_actualizacion_origen      INTO #Source     FROM [172.23.1.180\MSSQLSERVER,51601].[aval_reporteria].[dbo].rpt_gestiones_pagos_final AS t     INNER JOIN analitica.dim_cartera AS p         ON p.clave_cliente = @client_key        AND p.id_cartera_origen = t.nId_Cartera        AND p.unidad_negocio_origen = @business_unit_name     WHERE t.cCli_Nombre COLLATE DATABASE_DEFAULT           = @nombre_cliente_origen COLLATE DATABASE_DEFAULT       AND t.anio = @anio_campana       AND t.nCampCar = @mes_campana       AND t.dDocCobOpe_FecIni >= @campaign_start       AND t.dDocCobOpe_FecIni < @end_exclusive       AND UPPER(LTRIM(RTRIM(ISNULL(t.estado_pdp, ''))))           NOT LIKE '%PAGO SIN PROMESA%';      CREATE INDEX IX_Source_AdvisorDate         ON #Source(id_asesor_origen, clave_fecha, clave_cartera);      CREATE INDEX IX_Source_Operation         ON #Source(id_operacion_origen);      DECLARE @source_rows BIGINT;     DECLARE @source_as_of_at DATETIME2(3);     DECLARE @last_source_id BIGINT;      SELECT         @source_rows = COUNT_BIG(*),         @source_as_of_at = MAX(fecha_actualizacion_origen),         @last_source_id = MAX(id_operacion_origen)     FROM #Source;      IF ISNULL(@source_rows, 0) = 0         THROW 51804, 'No hay gestiones CLARO en el scope solicitado.', 1;       /* ============================================================        2. Guardas de identidad        ============================================================ */      IF EXISTS     (         SELECT 1         FROM #Source         WHERE ISNULL(id_asesor_origen, 0) = 0     )         THROW 51805, 'Existen gestiones reales sin nId_Usuario.', 1;      IF EXISTS     (         SELECT id_asesor_origen         FROM #Source         GROUP BY id_asesor_origen         HAVING COUNT(DISTINCT nombre_asesor) > 1     )         THROW 51806, 'Un nId_Usuario está asociado a múltiples nombres en el scope.', 1;       /* ============================================================        3. Identidad descriptiva más reciente        ============================================================ */      IF OBJECT_ID('tempdb..#LatestAdvisor') IS NOT NULL         DROP TABLE #LatestAdvisor;      ;WITH Ranked AS     (         SELECT             id_asesor_origen,             nombre_asesor,             nombre_rol,             fecha_hora_gestion,             fecha_actualizacion_origen,             ROW_NUMBER() OVER             (                 PARTITION BY id_asesor_origen                 ORDER BY
                    CASE WHEN nombre_asesor IS NULL THEN 1 ELSE 0 END,
                    fecha_hora_gestion DESC,
                    fecha_actualizacion_origen DESC             ) AS rn         FROM #Source     )     SELECT
        r.id_asesor_origen,
        COALESCE
        (
            r.nombre_asesor,
            NULLIF
            (
                LTRIM(RTRIM(CONCAT(
                    ISNULL(u.cUsr_Nombres, ''),
                    CASE
                        WHEN NULLIF(LTRIM(RTRIM(u.cUsr_ApePat)), '') IS NOT NULL
                            THEN ' '
                        ELSE ''
                    END,
                    ISNULL(u.cUsr_ApePat, ''),
                    CASE
                        WHEN NULLIF(LTRIM(RTRIM(u.cUsr_ApeMat)), '') IS NOT NULL
                            THEN ' '
                        ELSE ''
                    END,
                    ISNULL(u.cUsr_ApeMat, '')
                ))),
                ''
            )
        ) AS nombre_asesor,
        r.nombre_rol
    INTO #LatestAdvisor
    FROM Ranked AS r
    LEFT JOIN dbo.av_Usuario AS u
        ON u.nId_Usuario = r.id_asesor_origen
    WHERE r.rn = 1;       /* ============================================================        4. DNI más reciente dentro del MISMO scope CLARO         RPTC puede contener valores históricos corregidos y observaciones        fuera del scope solicitado.         Regla:        - se consideran únicamente pares nId_Usuario + nId_Cartera          presentes realmente en #Source;        - se restringe al rango temporal solicitado;        - se toma el DNI no nulo de la fecha más reciente por asesor;        - si en esa fecha existen varios DNI distintos para el mismo          nId_Usuario, la identidad continúa siendo ambigua y se aborta.        ============================================================ */      IF OBJECT_ID('tempdb..#DniScope') IS NOT NULL         DROP TABLE #DniScope;      CREATE TABLE #DniScope     (         id_asesor_origen INT NOT NULL,         dni_date DATE NOT NULL,         documento_asesor VARCHAR(50) NOT NULL     );      INSERT INTO #DniScope     (         id_asesor_origen,         dni_date,         documento_asesor     )     SELECT DISTINCT         CONVERT(INT, r.NID_USUARIO),         CONVERT(DATE, r.FEC_CORTA),         CONVERT(VARCHAR(50), NULLIF(LTRIM(RTRIM(r.USU_DNI)), ''))     FROM [172.23.1.180\MSSQLSERVER,51601].[aval_reporteria].[dbo].RPTC_253_PRODUCCIONGENERALPORGESTOR_ACUMULADO AS r     INNER JOIN     (         SELECT DISTINCT             id_asesor_origen,             nId_Cartera         FROM #Source     ) AS s         ON s.id_asesor_origen = CONVERT(INT, r.NID_USUARIO)        AND s.nId_Cartera = r.IDCARTERA     WHERE r.FEC_CORTA >= @campaign_start       AND r.FEC_CORTA <= @as_of_date       AND NULLIF(LTRIM(RTRIM(r.USU_DNI)), '') IS NOT NULL;      IF OBJECT_ID('tempdb..#AdvisorDni') IS NOT NULL         DROP TABLE #AdvisorDni;      ;WITH LatestDniDate AS     (         SELECT             id_asesor_origen,             MAX(dni_date) AS latest_dni_date         FROM #DniScope         GROUP BY id_asesor_origen     )     SELECT         d.id_asesor_origen,         COUNT(DISTINCT d.documento_asesor) AS distinct_dni,         MIN(d.documento_asesor) AS documento_asesor     INTO #AdvisorDni     FROM #DniScope AS d     INNER JOIN LatestDniDate AS l         ON l.id_asesor_origen = d.id_asesor_origen        AND l.latest_dni_date = d.dni_date     GROUP BY d.id_asesor_origen;      IF EXISTS     (         SELECT 1         FROM #AdvisorDni         WHERE distinct_dni > 1     )         THROW 51807,             'Conflicto de DNI vigente por nId_Usuario dentro del scope CLARO.',             1;      /* ============================================================        5. Upsert dim_advisor        ============================================================ */      UPDATE a     SET         a.documento_asesor = d.documento_asesor,         a.nombre_asesor = COALESCE(
            l.nombre_asesor,
            a.nombre_asesor
        ),         a.nombre_rol = l.nombre_rol,         a.es_activo = 1,         a.fecha_actualizacion = SYSUTCDATETIME()     FROM analitica.dim_asesor AS a     INNER JOIN #LatestAdvisor AS l         ON a.clave_cliente = @client_key        AND a.id_asesor_origen = CONVERT(VARCHAR(50), l.id_asesor_origen)     LEFT JOIN #AdvisorDni AS d         ON d.id_asesor_origen = l.id_asesor_origen;      INSERT INTO analitica.dim_asesor     (         clave_cliente,         id_asesor_origen,         documento_asesor,         nombre_asesor,         nombre_rol,         es_activo     )     SELECT         @client_key,         CONVERT(VARCHAR(50), l.id_asesor_origen),         d.documento_asesor,         l.nombre_asesor,         l.nombre_rol,         1     FROM #LatestAdvisor AS l     LEFT JOIN #AdvisorDni AS d         ON d.id_asesor_origen = l.id_asesor_origen     WHERE NOT EXISTS     (         SELECT 1         FROM analitica.dim_asesor AS a         WHERE a.clave_cliente = @client_key           AND a.id_asesor_origen =               CONVERT(VARCHAR(50), l.id_asesor_origen)     );       /* ============================================================        6. Mapa source -> surrogate        ============================================================ */      IF OBJECT_ID('tempdb..#AdvisorMap') IS NOT NULL         DROP TABLE #AdvisorMap;      SELECT         CONVERT(INT, a.id_asesor_origen) AS id_asesor_origen,         a.clave_asesor     INTO #AdvisorMap     FROM analitica.dim_asesor AS a     WHERE a.clave_cliente = @client_key       AND a.id_asesor_origen IN       (           SELECT CONVERT(VARCHAR(50), id_asesor_origen)           FROM #LatestAdvisor       );       /* ============================================================        7. Clasificación de contacto por debtor/day/advisor         Precedencia:        CD > CI > NC         El grain detallado se conserva porque sumar los distinct diarios        de fact_advisor_daily NO produce un distinct exacto multi-día.        ============================================================ */      IF OBJECT_ID('tempdb..#AdvisorDebtorContactDaily') IS NOT NULL         DROP TABLE #AdvisorDebtorContactDaily;      SELECT         s.clave_fecha,         s.clave_cartera,         m.clave_asesor,         s.id_deudor_origen,          CONVERT(             BIT,             MAX(CASE WHEN s.contact_code = 'CD' THEN 1 ELSE 0 END)         ) AS indicador_contacto_directo,          CONVERT(             BIT,             MAX(CASE WHEN s.contact_code = 'CI' THEN 1 ELSE 0 END)         ) AS indicador_contacto_indirecto,          CONVERT(             BIT,             MAX(CASE WHEN s.contact_code = 'NC' THEN 1 ELSE 0 END)         ) AS indicador_sin_contacto      INTO #AdvisorDebtorContactDaily     FROM #Source AS s     INNER JOIN #AdvisorMap AS m         ON m.id_asesor_origen = s.id_asesor_origen     GROUP BY         s.clave_fecha,         s.clave_cartera,         m.clave_asesor,         s.id_deudor_origen;      CREATE UNIQUE INDEX UX_AdvisorDebtorContactDaily_Grain         ON #AdvisorDebtorContactDaily         (             clave_fecha,             clave_cartera,             clave_asesor,             id_deudor_origen         );       IF OBJECT_ID('tempdb..#ContactDaily') IS NOT NULL         DROP TABLE #ContactDaily;      SELECT         clave_fecha,         clave_cartera,         clave_asesor,          SUM(CASE WHEN indicador_contacto_directo = 1 THEN 1 ELSE 0 END)             AS clientes_contacto_directo,          SUM(             CASE                 WHEN indicador_contacto_directo = 0                  AND indicador_contacto_indirecto = 1                     THEN 1                 ELSE 0             END         ) AS clientes_contacto_indirecto,          SUM(             CASE                 WHEN indicador_contacto_directo = 0                  AND indicador_contacto_indirecto = 0                  AND indicador_sin_contacto = 1                     THEN 1                 ELSE 0             END         ) AS clientes_sin_contacto      INTO #ContactDaily     FROM #AdvisorDebtorContactDaily     GROUP BY         clave_fecha,         clave_cartera,         clave_asesor;       /* ============================================================        8. Pagadores por debtor/day/advisor         El grain se persiste separado del contacto porque pago y contacto        son hechos distintos. Solo se incluyen pagos atribuibles a gestiones        reales; Pago Sin Promesa ya fue excluido de #Source.        ============================================================ */      IF OBJECT_ID('tempdb..#AdvisorDebtorPayerDaily') IS NOT NULL         DROP TABLE #AdvisorDebtorPayerDaily;      SELECT         s.clave_fecha,         s.clave_cartera,         m.clave_asesor,         s.id_deudor_origen     INTO #AdvisorDebtorPayerDaily     FROM #Source AS s     INNER JOIN #AdvisorMap AS m         ON m.id_asesor_origen = s.id_asesor_origen     WHERE s.monto_pagado > 0     GROUP BY         s.clave_fecha,         s.clave_cartera,         m.clave_asesor,         s.id_deudor_origen;      CREATE UNIQUE INDEX UX_AdvisorDebtorPayerDaily_Grain         ON #AdvisorDebtorPayerDaily         (             clave_fecha,             clave_cartera,             clave_asesor,             id_deudor_origen         );       IF OBJECT_ID('tempdb..#PayerDaily') IS NOT NULL         DROP TABLE #PayerDaily;      SELECT         clave_fecha,         clave_cartera,         clave_asesor,         COUNT_BIG(*) AS cantidad_pagadores     INTO #PayerDaily     FROM #AdvisorDebtorPayerDaily     GROUP BY         clave_fecha,         clave_cartera,         clave_asesor;       /* ============================================================        9. Producción diaria base        ============================================================ */      IF OBJECT_ID('tempdb..#AdvisorDaily') IS NOT NULL         DROP TABLE #AdvisorDaily;      ;WITH Base AS     (         SELECT             s.clave_fecha,             s.clave_cartera,             m.clave_asesor,              COUNT_BIG(*) AS eventos_gestion,              SUM(                 CASE                     WHEN s.is_valid_promise_source = 1                      AND s.monto_promesa > 0                      AND UPPER(ISNULL(s.estado_origen, ''))                          NOT LIKE '%NO PDP%'                         THEN 1                     ELSE 0                 END             ) AS cantidad_promesas,              SUM(                 CASE                     WHEN s.is_valid_promise_source = 1                      AND s.monto_promesa > 0                      AND UPPER(ISNULL(s.estado_origen, ''))                          NOT LIKE '%NO PDP%'                         THEN s.monto_promesa                     ELSE CONVERT(DECIMAL(19,4), 0)                 END             ) AS monto_promesas,              SUM(s.monto_pagado) AS monto_recuperado          FROM #Source AS s         INNER JOIN #AdvisorMap AS m             ON m.id_asesor_origen = s.id_asesor_origen         GROUP BY             s.clave_fecha,             s.clave_cartera,             m.clave_asesor     )     SELECT         b.clave_fecha,         b.clave_cartera,         b.clave_asesor,          CONVERT(INT, b.eventos_gestion)             AS eventos_gestion,          CONVERT(INT, ISNULL(c.clientes_contacto_directo, 0))             AS clientes_contacto_directo,          CONVERT(INT, ISNULL(c.clientes_contacto_indirecto, 0))             AS clientes_contacto_indirecto,          CONVERT(INT, ISNULL(c.clientes_sin_contacto, 0))             AS clientes_sin_contacto,          CONVERT(INT, b.cantidad_promesas)             AS cantidad_promesas,          CONVERT(DECIMAL(19,4), b.monto_promesas)             AS monto_promesas,          CONVERT(INT, ISNULL(py.cantidad_pagadores, 0))             AS cantidad_pagadores,          CONVERT(DECIMAL(19,4), b.monto_recuperado)             AS monto_recuperado      INTO #AdvisorDaily     FROM Base AS b     LEFT JOIN #ContactDaily AS c         ON c.clave_fecha = b.clave_fecha        AND c.clave_cartera = b.clave_cartera        AND c.clave_asesor = b.clave_asesor     LEFT JOIN #PayerDaily AS py         ON py.clave_fecha = b.clave_fecha        AND py.clave_cartera = b.clave_cartera        AND py.clave_asesor = b.clave_asesor;       /* ============================================================        10. Mapeo de fact_promise -> advisor        ============================================================ */      IF OBJECT_ID('tempdb..#OperationAdvisor') IS NOT NULL         DROP TABLE #OperationAdvisor;      SELECT         s.id_operacion_origen,         MIN(m.clave_asesor) AS clave_asesor,         COUNT(DISTINCT m.clave_asesor) AS distinct_advisors     INTO #OperationAdvisor     FROM #Source AS s     INNER JOIN #AdvisorMap AS m         ON m.id_asesor_origen = s.id_asesor_origen     WHERE s.id_operacion_origen IS NOT NULL     GROUP BY s.id_operacion_origen;      IF EXISTS     (         SELECT 1         FROM #OperationAdvisor         WHERE distinct_advisors > 1     )         THROW 51808, 'Una operación está asociada a múltiples asesores.', 1;       /* ============================================================        11. Escritura idempotente        ============================================================ */      BEGIN TRY         BEGIN TRANSACTION;          /*           El detalle advisor/debtor/contact y la fact diaria pertenecen           enteramente a este adaptador para CLARO V1. Reemplazar MTD evita           mantener filas obsoletas y conserva idempotencia.         */         DELETE f         FROM analitica.hecho_contacto_deudor_asesor_diario AS f         INNER JOIN analitica.dim_fecha AS d             ON d.clave_fecha = f.clave_fecha         WHERE f.clave_cliente = @client_key           AND f.clave_campana = @campaign_key           AND d.fecha_calendario >= @campaign_start           AND d.fecha_calendario <= @as_of_date           AND EXISTS           (               SELECT 1               FROM analitica.dim_cartera AS bp               WHERE bp.clave_cartera = f.clave_cartera                 AND bp.clave_cliente = @client_key                 AND bp.unidad_negocio_origen = @business_unit_name           );          INSERT INTO analitica.hecho_contacto_deudor_asesor_diario         (             clave_fecha,             clave_cliente,             clave_campana,             clave_cartera,             clave_asesor,             id_deudor_origen,             indicador_contacto_directo,             indicador_contacto_indirecto,             indicador_sin_contacto,             fecha_corte_origen         )         SELECT             d.clave_fecha,             @client_key,             @campaign_key,             d.clave_cartera,             d.clave_asesor,             d.id_deudor_origen,             d.indicador_contacto_directo,             d.indicador_contacto_indirecto,             d.indicador_sin_contacto,             @source_as_of_at         FROM #AdvisorDebtorContactDaily AS d;           DELETE f         FROM analitica.hecho_pago_deudor_asesor_diario AS f         INNER JOIN analitica.dim_fecha AS d             ON d.clave_fecha = f.clave_fecha         WHERE f.clave_cliente = @client_key           AND f.clave_campana = @campaign_key           AND d.fecha_calendario >= @campaign_start           AND d.fecha_calendario <= @as_of_date           AND EXISTS           (               SELECT 1               FROM analitica.dim_cartera AS bp               WHERE bp.clave_cartera = f.clave_cartera                 AND bp.clave_cliente = @client_key                 AND bp.unidad_negocio_origen = @business_unit_name           );          INSERT INTO analitica.hecho_pago_deudor_asesor_diario         (             clave_fecha,             clave_cliente,             clave_campana,             clave_cartera,             clave_asesor,             id_deudor_origen,             fecha_corte_origen         )         SELECT             d.clave_fecha,             @client_key,             @campaign_key,             d.clave_cartera,             d.clave_asesor,             d.id_deudor_origen,             @source_as_of_at         FROM #AdvisorDebtorPayerDaily AS d;           DELETE f         FROM analitica.hecho_asesor_diario AS f         INNER JOIN analitica.dim_fecha AS d             ON d.clave_fecha = f.clave_fecha         WHERE f.clave_cliente = @client_key           AND f.clave_campana = @campaign_key           AND d.fecha_calendario >= @campaign_start           AND d.fecha_calendario <= @as_of_date           AND EXISTS           (               SELECT 1               FROM analitica.dim_cartera AS bp               WHERE bp.clave_cartera = f.clave_cartera                 AND bp.clave_cliente = @client_key                 AND bp.unidad_negocio_origen = @business_unit_name           );          INSERT INTO analitica.hecho_asesor_diario         (             clave_fecha,             clave_cliente,             clave_campana,             clave_cartera,             clave_asesor,              eventos_gestion,             clientes_contacto_directo,             clientes_contacto_indirecto,             clientes_sin_contacto,             cantidad_promesas,             monto_promesas,             cantidad_pagadores,             monto_recuperado,              fecha_corte_origen         )         SELECT             d.clave_fecha,             @client_key,             @campaign_key,             d.clave_cartera,             d.clave_asesor,              d.eventos_gestion,             d.clientes_contacto_directo,             d.clientes_contacto_indirecto,             d.clientes_sin_contacto,             d.cantidad_promesas,             d.monto_promesas,             d.cantidad_pagadores,             d.monto_recuperado,              @source_as_of_at         FROM #AdvisorDaily AS d;          /*           Completa clave_asesor de las promesas ya materializadas por el           ETL live. Solo toca operaciones que tienen un mapping inequívoco.         */         UPDATE p         SET             p.clave_asesor = o.clave_asesor,             p.fecha_carga = SYSUTCDATETIME()         FROM analitica.hecho_promesa AS p         INNER JOIN #OperationAdvisor AS o             ON o.id_operacion_origen = p.id_operacion_origen         WHERE p.clave_cliente = @client_key           AND p.clave_campana = @campaign_key;           /* Watermark independiente del ETL live */         UPDATE integracion_datos_analitica.control_carga         SET             fecha_ultimo_exito = SYSUTCDATETIME(),             fecha_hora_ultimo_origen = @source_as_of_at,             id_ultimo_origen = @last_source_id,             dias_solapamiento = 0,             fecha_actualizacion = SYSUTCDATETIME()         WHERE codigo_origen = @watermark_source_code;          IF @@ROWCOUNT = 0         BEGIN             INSERT INTO integracion_datos_analitica.control_carga             (                 codigo_origen,                 fecha_ultimo_exito,                 fecha_hora_ultimo_origen,                 id_ultimo_origen,                 dias_solapamiento             )             VALUES             (                 @watermark_source_code,                 SYSUTCDATETIME(),                 @source_as_of_at,                 @last_source_id,                 0             );         END;          COMMIT TRANSACTION;           /* ============================================================            12. Resumen            ============================================================ */          SELECT             @codigo_campana AS codigo_campana,             @codigo_unidad_negocio AS codigo_unidad_negocio,             @business_unit_name AS unidad_negocio_origen,             @fecha_corte AS requested_as_of_at,             @source_as_of_at AS fecha_corte_origen,             @source_rows AS source_management_rows,              (                 SELECT COUNT(*)                 FROM #LatestAdvisor             ) AS advisors_in_source,              (                 SELECT COUNT(*)                 FROM #AdvisorDni                 WHERE distinct_dni = 1                   AND documento_asesor IS NOT NULL             ) AS advisors_with_dni,              (                 SELECT COUNT(*)                 FROM #AdvisorDebtorContactDaily             ) AS advisor_debtor_contact_rows,              (                 SELECT COUNT(*)                 FROM #AdvisorDebtorPayerDaily             ) AS advisor_debtor_payer_rows,              SUM(d.eventos_gestion) AS eventos_gestion,             SUM(d.clientes_contacto_directo) AS clientes_contacto_directo,             SUM(d.clientes_contacto_indirecto) AS clientes_contacto_indirecto,             SUM(d.clientes_sin_contacto) AS clientes_sin_contacto,             SUM(d.cantidad_promesas) AS cantidad_promesas,             SUM(d.monto_promesas) AS monto_promesas,             SUM(d.cantidad_pagadores) AS cantidad_pagadores,             SUM(d.monto_recuperado) AS attributable_recovered_amount,              (                 SELECT COUNT(*)                 FROM analitica.hecho_promesa AS p                 INNER JOIN analitica.dim_cartera AS bp                     ON bp.clave_cartera = p.clave_cartera                    AND bp.clave_cliente = @client_key                    AND bp.unidad_negocio_origen = @business_unit_name                 WHERE p.clave_cliente = @client_key                   AND p.clave_campana = @campaign_key                   AND p.es_promesa_valida = 1                   AND p.clave_asesor IS NOT NULL             ) AS valid_promises_with_advisor          FROM #AdvisorDaily AS d;      END TRY     BEGIN CATCH         IF @@TRANCOUNT > 0             ROLLBACK TRANSACTION;          THROW;     END CATCH; END;
GO
